import React, { useEffect, useMemo, useState } from "react";
import { Link, NavLink, Outlet, useNavigate, useParams } from "react-router-dom";
import {
  BarChart3,
  Box,
  LayoutDashboard,
  LineChart,
  LogOut,
  Menu,
  Package,
  PlusCircle,
  Settings,
  ShoppingCart,
  Star,
  X
} from "lucide-react";
import { useAuth } from "./AuthContext";
import { useTheme } from "./ThemeContext";
import { apiFetch } from "./api";
import { PRODUCT_CATEGORY_VALUES, refFromId } from "./catalog";
import { h, f } from "./h";
import {
  Badge,
  Button,
  Field,
  GlassCard,
  GlassPanel,
  LogoMark,
  RefImage,
  SelectInput,
  TextArea,
  TextInput,
  ThemeToggleButton
} from "./ui";

function NavItem({ to, icon: Icon, children, badge }) {
  return h(NavLink, {
    to,
    className: ({ isActive }) =>
      `flex items-center justify-between gap-2 rounded-2xl px-3 py-2.5 text-sm font-medium transition sm:px-4 sm:text-base ${
        isActive
          ? "bg-gradient-to-r from-sky-600/90 to-blue-700/90 text-white shadow-lg shadow-sky-900/30"
          : "text-slate-700 hover:bg-white/40 dark:text-slate-200 dark:hover:bg-white/10"
      }`,
    children: ({ isActive }) =>
      h(f, null, [
        h("span", { className: "flex items-center gap-2" }, [
          h(Icon, { className: `h-4 w-4 sm:h-5 sm:w-5 ${isActive ? "text-white" : ""}` }),
          children
        ]),
        badge != null &&
          badge > 0 &&
          h(
            "span",
            {
              className: `rounded-full px-2 py-0.5 text-[10px] font-bold ${
                isActive ? "bg-white/20 text-white" : "bg-amber-400/20 text-amber-800 dark:text-amber-200"
              }`
            },
            String(badge)
          )
      ])
  });
}

function humanizeOrderStatus(s) {
  return String(s || "")
    .replace(/_/g, " ")
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

export function VendorShell() {
  const { dark, toggle } = useTheme();
  const { user, accessToken, logout } = useAuth();
  const nav = useNavigate();
  const [open, setOpen] = useState(false);
  const [orderBadge, setOrderBadge] = useState(0);

  useEffect(() => {
    if (!accessToken || user?.role !== "seller") {
      setOrderBadge(0);
      return;
    }
    let cancelled = false;
    apiFetch("/api/vendor/orders", { headers: { Authorization: `Bearer ${accessToken}` } })
      .then((d) => {
        if (cancelled) return;
        const list = d.orders || [];
        const n = list.filter((o) => ["pending_payment", "paid", "processing", "shipped"].includes(o.status)).length;
        setOrderBadge(n);
      })
      .catch(() => {
        if (!cancelled) setOrderBadge(0);
      });
    return () => {
      cancelled = true;
    };
  }, [accessToken, user?.role]);

  const onLogout = async () => {
    await logout();
    nav("/login", { replace: true });
  };

  const sidebar = h(
    "aside",
    {
      className: `fixed inset-y-0 left-0 z-40 w-72 max-w-[85vw] border-r border-white/10 bg-white/35 p-4 shadow-2xl backdrop-blur-2xl transition-transform dark:bg-night-900/50 lg:static lg:translate-x-0 ${
        open ? "translate-x-0" : "-translate-x-full lg:translate-x-0"
      }`
    },
    [
      h("div", { className: "mb-6 flex items-center justify-between gap-2 lg:hidden" }, [
        h("span", { className: "font-display text-lg font-bold text-slate-900 dark:text-white" }, "Menu"),
        h("div", { className: "flex items-center gap-2" }, [
          h(ThemeToggleButton, { dark, onToggle: toggle }),
          h(
            "button",
            {
              type: "button",
              className: "tap-target rounded-xl p-2 hover:bg-white/10",
              onClick: () => setOpen(false)
            },
            h(X, { className: "h-5 w-5" })
          )
        ])
      ]),
      h("div", { className: "mb-6 hidden items-center justify-between lg:flex" }, [
        h("span", { className: "text-[10px] font-bold uppercase tracking-widest text-slate-500 dark:text-slate-400" }, "Theme"),
        h(ThemeToggleButton, { dark, onToggle: toggle })
      ]),
      h("div", { className: "mb-6 text-[10px] font-bold uppercase tracking-widest text-slate-500 dark:text-slate-400" }, "Main"),
      h("nav", { className: "space-y-1" }, [
        h(NavItem, { to: "/vendor/dashboard", icon: LayoutDashboard }, "Dashboard"),
        h(NavItem, { to: "/vendor/products", icon: Box }, "My products"),
        h(NavItem, { to: "/vendor/products/new", icon: PlusCircle }, "Add product"),
        h(NavItem, { to: "/vendor/orders", icon: ShoppingCart, badge: orderBadge }, "Orders")
      ]),
      h("div", { className: "mb-2 mt-6 text-[10px] font-bold uppercase tracking-widest text-slate-500 dark:text-slate-400" }, "Insights"),
      h("nav", { className: "space-y-1" }, [
        h(NavItem, { to: "/vendor/analytics", icon: LineChart }, "Analytics"),
        h(NavItem, { to: "/vendor/reviews", icon: Star }, "Reviews")
      ]),
      h("div", { className: "mb-2 mt-6 text-[10px] font-bold uppercase tracking-widest text-slate-500 dark:text-slate-400" }, "Settings"),
      h("nav", { className: "space-y-1" }, [
        h(NavItem, { to: "/vendor/settings", icon: Settings }, "Store settings"),
        h(
          "button",
          {
            type: "button",
            onClick: onLogout,
            className:
              "flex w-full items-center gap-2 rounded-2xl px-3 py-2.5 text-left text-sm font-medium text-rose-400 hover:bg-rose-500/10 sm:px-4 sm:text-base"
          },
          [h(LogOut, { className: "h-4 w-4 sm:h-5 sm:w-5" }), "Logout"]
        )
      ]),
      h(
        GlassCard,
        { className: "mt-6 !border-sky-500/20 !bg-gradient-to-br !from-sky-900/80 !to-night-950 !p-4" },
        [
          h("p", { className: "text-xs font-bold uppercase tracking-wide text-sky-200" }, "Vendor hub"),
          h("p", { className: "mt-1 text-xs text-white/80" }, "Manage listings, orders, and payouts from one place.")
        ]
      )
    ]
  );

  return h("div", { className: "min-h-screen bg-slate-100 dark:bg-night-950 dark:bg-mesh-dark" }, [
    open &&
      h("button", {
        type: "button",
        className: "fixed inset-0 z-30 bg-slate-950/50 backdrop-blur-sm lg:hidden",
        onClick: () => setOpen(false),
        "aria-label": "Close menu"
      }),
    h("div", { className: "flex min-h-screen" }, [
      sidebar,
      h("div", { className: "flex min-h-screen flex-1 flex-col" }, [
        h(
          "header",
          {
            className:
              "sticky top-0 z-20 border-b border-white/10 bg-white/30 px-4 py-3 backdrop-blur-xl dark:bg-night-900/40 sm:px-6"
          },
          h("div", { className: "mx-auto flex max-w-7xl items-center justify-between gap-3" }, [
            h(
              "button",
              {
                type: "button",
                className: "tap-target rounded-2xl border border-white/15 p-2 lg:hidden",
                onClick: () => setOpen(true)
              },
              h(Menu, { className: "h-5 w-5" })
            ),
            h("div", { className: "flex items-center gap-2" }, [
              h(LogoMark, { className: "h-9 w-9" }),
              h("span", { className: "font-display text-lg font-bold text-slate-900 dark:text-white" }, "BrewMart"),
              h(
                "span",
                {
                  className:
                    "hidden rounded-full bg-amber-400/20 px-2 py-0.5 text-[10px] font-bold uppercase text-amber-900 dark:text-amber-200 sm:inline"
                },
                "Vendor"
              )
            ]),
            h(
              "nav",
              { className: "hidden flex-1 justify-center gap-1 md:flex" },
              [
                ["Dashboard", "/vendor/dashboard"],
                ["Products", "/vendor/products"],
                ["Orders", "/vendor/orders"],
                ["Analytics", "/vendor/analytics"],
                ["Profile", "/vendor/profile"]
              ].map(([label, path]) =>
                h(
                  NavLink,
                  {
                    key: path,
                    to: path,
                    className: ({ isActive }) =>
                      `rounded-full px-3 py-2 text-sm font-medium ${
                        isActive
                          ? "bg-sky-500/15 text-sky-800 dark:text-sky-200"
                          : "text-slate-600 hover:bg-white/40 dark:text-slate-300 dark:hover:bg-white/10"
                      }`
                  },
                  label
                )
              )
            ),
            h("div", { className: "flex items-center gap-2" }, [
              h(ThemeToggleButton, { dark, onToggle: toggle }),
              h("div", { className: "hidden items-center gap-2 rounded-2xl border border-white/10 bg-white/20 px-2 py-1 sm:flex dark:bg-white/5" }, [
                h(
                  "span",
                  {
                    className: "flex h-8 w-8 items-center justify-center rounded-full bg-sky-600 text-sm font-bold text-white"
                  },
                  (user?.email?.[0] || "V").toUpperCase()
                ),
                h(
                  "span",
                  { className: "max-w-[120px] truncate text-xs font-medium text-slate-800 dark:text-slate-100" },
                  user?.displayName || user?.email || "Vendor"
                )
              ]),
              h(
                Link,
                { to: "/shop" },
                h(Button, { variant: "primary", className: "!min-h-[40px] !rounded-full !px-4 !text-sm" }, "Buyer view")
              )
            ])
          ])
        ),
        h("main", { className: "mx-auto w-full max-w-7xl flex-1 px-4 py-6 sm:px-6" }, h(Outlet))
      ])
    ])
  ]);
}

function KpiIcon({ name }) {
  const map = {
    wallet: Package,
    package: Box,
    "shopping-bag": ShoppingCart,
    star: Star
  };
  const Icon = map[name] || BarChart3;
  return h(
    "div",
    {
      className:
        "flex h-11 w-11 items-center justify-center rounded-2xl bg-sky-500/15 text-sky-600 dark:text-sky-300"
    },
    h(Icon, { className: "h-5 w-5" })
  );
}

export function VendorDashboardPage() {
  const { accessToken, user } = useAuth();
  const [analytics, setAnalytics] = useState(null);
  const [recentOrders, setRecentOrders] = useState([]);
  const [err, setErr] = useState("");

  useEffect(() => {
    if (!accessToken) return;
    let cancelled = false;
    Promise.all([
      apiFetch("/api/vendor/analytics", { headers: { Authorization: `Bearer ${accessToken}` } }),
      apiFetch("/api/vendor/orders", { headers: { Authorization: `Bearer ${accessToken}` } })
    ])
      .then(([a, o]) => {
        if (cancelled) return;
        setAnalytics(a);
        setRecentOrders((o.orders || []).slice(0, 5));
      })
      .catch((ex) => {
        if (!cancelled) setErr(ex.message || "Failed to load dashboard");
      });
    return () => {
      cancelled = true;
    };
  }, [accessToken]);

  const kpis = useMemo(() => {
    if (!analytics) return [];
    return [
      { label: "Active listings", value: String(analytics.productCount ?? 0), delta: "Products", icon: "package" },
      { label: "Orders (paid+)", value: String(analytics.orderCount ?? 0), delta: "All time", icon: "shopping-bag" },
      { label: "Gross revenue", value: `$${Number(analytics.revenue || 0).toFixed(2)}`, delta: "Your lines", icon: "wallet" },
      { label: "Reviews", value: String(analytics.reviewCount ?? 0), delta: "On your products", icon: "star" }
    ];
  }, [analytics]);

  const bars = useMemo(() => {
    const tp = analytics?.topProducts || [];
    if (!tp.length) return [20, 25, 30, 35, 40, 45, 50];
    const max = Math.max(...tp.map((x) => x.revenue), 1);
    return tp.slice(0, 7).map((x) => Math.round((x.revenue / max) * 100));
  }, [analytics]);

  const greet = user?.displayName?.trim() || user?.email?.split("@")[0] || "there";

  return h(f, null, [
    err && h("p", { key: "err", className: "mb-4 text-sm text-rose-400" }, err),
    !analytics && !err && h("p", { key: "loading", className: "mb-4 text-sm text-slate-500 dark:text-slate-400" }, "Loading dashboard…"),
    h("div", { key: "hero", className: "mb-6 flex flex-wrap items-center justify-between gap-3" }, [
      h("div", { key: "hero-copy" }, [
        h("h1", { key: "title", className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, `Good day, ${greet}`),
        h("p", { key: "subtitle", className: "text-sm text-slate-600 dark:text-slate-400" }, "Here is how your store is performing.")
      ]),
      h(
        Link,
        { key: "add-link", to: "/vendor/products/new" },
        h(Button, { className: "!rounded-full" }, [h(PlusCircle, { key: "ic", className: "h-4 w-4" }), h("span", { key: "tx" }, "Add product")])
      )
    ]),
    h("div", { key: "kpis", className: "mb-8 grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4" }, [
      kpis.map((k) =>
        h(GlassCard, { key: k.label }, [
          h("div", { className: "flex items-start justify-between gap-3" }, [
            h("div", {}, [
              h("p", { className: "text-xs font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400" }, k.label),
              h("p", { className: "mt-2 text-2xl font-bold text-slate-900 dark:text-white" }, k.value),
              h("p", { className: "mt-1 text-xs font-medium text-emerald-500 dark:text-emerald-400" }, k.delta)
            ]),
            h(KpiIcon, { name: k.icon })
          ])
        ])
      )
    ]),
    h("div", { key: "charts", className: "grid grid-cols-1 gap-6 lg:grid-cols-3" }, [
      h(GlassPanel, { key: "revenue-panel", className: "lg:col-span-2" }, [
        h("div", { key: "revenue-head", className: "mb-4 flex items-center justify-between" }, [
          h("h2", { key: "title", className: "text-lg font-semibold text-slate-900 dark:text-white" }, "Revenue snapshot"),
          h("span", { key: "note", className: "text-xs text-slate-500 dark:text-slate-400" }, "Scaled from your top products")
        ]),
        h(
          "div",
          { className: "flex h-48 items-end justify-between gap-2 rounded-2xl border border-white/10 bg-night-900/40 p-4" },
          bars.map((hgt, i) =>
            h(
              "div",
              { key: i, className: "flex flex-1 flex-col items-center gap-2" },
              [
                h("div", { key: "bar",
                  className: "w-full max-w-[2.5rem] rounded-t-xl bg-gradient-to-t from-sky-600 to-sky-400 transition-all",
                  style: { height: `${Math.max(8, hgt)}%` }
                }),
                h("span", { key: "day", className: "text-[10px] text-slate-500 dark:text-slate-400" }, ["M", "T", "W", "T", "F", "S", "S"][i] || "")
              ]
            )
          )
        )
      ]),
      h(GlassPanel, { key: "top-products" }, [
        h("h2", { key: "title", className: "text-lg font-semibold text-slate-900 dark:text-white" }, "Top products"),
        h(
          "ul",
          { className: "mt-4 space-y-2 text-sm" },
          (analytics?.topProducts || []).slice(0, 5).map((r) =>
            h("li", { key: r.productId, className: "flex items-center justify-between gap-2" }, [
              h("span", { className: "truncate text-slate-600 dark:text-slate-300" }, r.name),
              h("span", { className: "shrink-0 font-semibold text-slate-900 dark:text-white" }, `$${Number(r.revenue).toFixed(2)}`)
            ])
          )
        ),
        (!analytics?.topProducts || analytics.topProducts.length === 0) &&
          h("p", { key: "empty", className: "mt-2 text-sm text-slate-500 dark:text-slate-400" }, "No sales yet — add products and share your shop.")
      ])
    ]),
    h("div", { key: "recent", className: "mt-8" }, [
      h("div", { key: "head", className: "mb-3 flex items-center justify-between" }, [
        h("h2", { key: "title", className: "text-lg font-semibold text-slate-900 dark:text-white" }, "Recent orders"),
        h(Link, { key: "view-all", to: "/vendor/orders", className: "text-sm font-semibold text-sky-600 hover:underline dark:text-sky-300" }, "View all →")
      ]),
      h(
        GlassCard,
        { className: "!overflow-hidden !p-0" },
        h(
          "div",
          { className: "divide-y divide-white/10" },
          recentOrders.length === 0
            ? h("p", { className: "px-4 py-6 text-sm text-slate-500 dark:text-slate-400" }, "No orders yet.")
            : recentOrders.map((o) =>
                h(
                  "div",
                  { key: o.id, className: "flex flex-wrap items-center justify-between gap-2 px-4 py-3" },
                  [
                    h("span", { className: "font-mono text-sm text-slate-600 dark:text-slate-300" }, `#${o.id.slice(-8)}`),
                    h("span", { className: "text-sm text-slate-900 dark:text-white" }, `$${Number(o.total).toFixed(2)}`),
                    h(Badge, { tone: "neutral" }, humanizeOrderStatus(o.status))
                  ]
                )
              )
        )
      )
    ])
  ]);
}

function productStatusTone(st) {
  if (st === "active") return "success";
  if (st === "draft") return "warn";
  return "neutral";
}

export function VendorProductsPage() {
  const { accessToken } = useAuth();
  const nav = useNavigate();
  const [rows, setRows] = useState([]);
  const [q, setQ] = useState("");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(true);

  const load = () => {
    if (!accessToken) return;
    setLoading(true);
    apiFetch("/api/products/mine", { headers: { Authorization: `Bearer ${accessToken}` } })
      .then((d) => setRows(d.products || []))
      .catch((ex) => setErr(ex.message || "Failed to load"))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    load();
  }, [accessToken]);

  const filtered = useMemo(() => {
    const t = q.trim().toLowerCase();
    if (!t) return rows;
    return rows.filter((p) => p.name?.toLowerCase().includes(t) || p.category?.toLowerCase().includes(t));
  }, [rows, q]);

  const del = async (id) => {
