export function VendorAddProductPage() {
  const { accessToken } = useAuth();
  const nav = useNavigate();
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [category, setCategory] = useState("beans");
  const [price, setPrice] = useState("");
  const [compareAtPrice, setCompareAtPrice] = useState("");
  const [stock, setStock] = useState("0");
  const [tags, setTags] = useState("");
  const [imageUrls, setImageUrls] = useState("");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);

  const submit = async (asDraft) => {
    setErr("");
    if (!accessToken) return;
    const trimmedName = name.trim();
    if (!trimmedName) {
      setErr("Product name is required.");
      return;
    }
    const priceNum = Number(price);
    if (!Number.isFinite(priceNum) || priceNum <= 0) {
      setErr("Enter a valid price greater than zero.");
      return;
    }
    setLoading(true);
    try {
      const tagList = tags
        .split(",")
        .map((s) => s.trim())
        .filter(Boolean)
        .slice(0, 10);
      const urls = imageUrls
        .split(/\n|,/)
        .map((s) => s.trim())
        .filter(Boolean)
        .slice(0, 8);
      const nextStatus = asDraft ? "draft" : "active";
      const compareNum = compareAtPrice === "" ? null : Number(compareAtPrice);
      const body = {
        name: trimmedName,
        description: description.trim(),
        category,
        price: priceNum,
        compareAtPrice: compareNum != null && Number.isFinite(compareNum) && compareNum > 0 ? compareNum : null,
        stock: Math.max(0, Math.floor(Number(stock) || 0)),
        status: nextStatus,
        tags: tagList,
        imageUrls: urls
      };
      await apiFetch("/api/products", {
        method: "POST",
        headers: { Authorization: `Bearer ${accessToken}` },
        json: body
      });
      nav("/vendor/products");
    } catch (ex) {
      setErr(ex.message || "Could not create product");
    } finally {
      setLoading(false);
    }
  };

  return h(f, null, [
    err && h("p", { className: "mb-4 text-sm text-rose-400" }, err),
    h("div", { className: "mb-6 flex flex-wrap items-center justify-between gap-3" }, [
      h("h1", { className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Add new product"),
      h(Link, { to: "/vendor/products" }, h(Button, { variant: "ghost", className: "!rounded-full" }, "← Back to products"))
    ]),
    h("div", { className: "grid grid-cols-1 gap-6 lg:grid-cols-3" }, [
      h("div", { className: "space-y-6 lg:col-span-2" }, [
        h(GlassPanel, {}, [
          h("h2", { className: "mb-4 font-semibold text-slate-900 dark:text-white" }, "Product details"),
          h("div", { className: "space-y-4" }, [
            h(Field, { label: "Product name" }, h(TextInput, { value: name, onChange: (e) => setName(e.target.value), placeholder: "Ethiopian Yirgacheffe beans" })),
            h(Field, { label: "Description" }, h(TextArea, { value: description, onChange: (e) => setDescription(e.target.value), placeholder: "Tell buyers what makes this special…" })),
            h("div", { className: "grid grid-cols-1 gap-4 sm:grid-cols-2" }, [
              h(Field, { label: "Price ($)" }, h(TextInput, { type: "number", step: "0.01", value: price, onChange: (e) => setPrice(e.target.value), placeholder: "18.99" })),
              h(Field, { label: "Compare at ($)" }, h(TextInput, { type: "number", step: "0.01", value: compareAtPrice, onChange: (e) => setCompareAtPrice(e.target.value), placeholder: "Optional" }))
            ]),
            h("div", { className: "grid grid-cols-1 gap-4 sm:grid-cols-2" }, [
              h(
                Field,
                { label: "Category" },
                h(
                  SelectInput,
                  { value: category, onChange: (e) => setCategory(e.target.value) },
                  PRODUCT_CATEGORY_VALUES.map((c) => h("option", { key: c, value: c }, c))
                )
              ),
              h(Field, { label: "Stock quantity" }, h(TextInput, { type: "number", value: stock, onChange: (e) => setStock(e.target.value), placeholder: "42" }))
            ]),
            h(Field, { label: "Tags (comma-separated)" }, h(TextInput, { value: tags, onChange: (e) => setTags(e.target.value), placeholder: "new, popular" })),
            h(Field, { label: "Image URLs (comma or newline separated)" }, h(TextArea, { value: imageUrls, onChange: (e) => setImageUrls(e.target.value), placeholder: "https://…" }))
          ])
        ])
      ]),
      h("div", { className: "space-y-6" }, [
        h(GlassPanel, {}, [
          h("h2", { className: "mb-4 font-semibold text-slate-900 dark:text-white" }, "Publish"),
          h(
            Button,
            {
              className: "mt-4 w-full",
              loading,
              type: "button",
              onClick: () => submit(false)
            },
            "Publish (active)"
          ),
          h(
            Button,
            { variant: "ghost", className: "mt-2 w-full", type: "button", disabled: loading, onClick: () => submit(true) },
            "Save as draft"
          )
        ])
      ])
    ])
  ]);
}

export function VendorEditProductPage() {
  const { productId } = useParams();
  const { accessToken } = useAuth();
  const nav = useNavigate();
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [category, setCategory] = useState("beans");
  const [price, setPrice] = useState("");
  const [compareAtPrice, setCompareAtPrice] = useState("");
  const [stock, setStock] = useState("0");
  const [status, setStatus] = useState("draft");
  const [tags, setTags] = useState("");
  const [imageUrls, setImageUrls] = useState("");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!accessToken || !productId) return;
    let cancelled = false;
    apiFetch(`/api/products/${productId}`, { headers: { Authorization: `Bearer ${accessToken}` } })
      .then((d) => {
        if (cancelled || !d.product) return;
        const p = d.product;
        setName(p.name || "");
        setDescription(p.description || "");
        setCategory(p.category || "beans");
        setPrice(String(p.price ?? ""));
        setCompareAtPrice(p.compareAtPrice != null ? String(p.compareAtPrice) : "");
        setStock(String(p.stock ?? 0));
        setStatus(p.status || "draft");
        setTags((p.tags || []).join(", "));
        setImageUrls((p.imageUrls || []).join("\n"));
      })
      .catch((ex) => {
        if (!cancelled) setErr(ex.message || "Failed to load");
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [accessToken, productId]);

  const save = async () => {
    setErr("");
    if (!accessToken || !productId) return;
    setSaving(true);
    try {
      const tagList = tags
        .split(",")
        .map((s) => s.trim())
        .filter(Boolean)
        .slice(0, 10);
      const urls = imageUrls
        .split(/\n|,/)
        .map((s) => s.trim())
        .filter(Boolean)
        .slice(0, 8);
      await apiFetch(`/api/products/${productId}`, {
        method: "PATCH",
        headers: { Authorization: `Bearer ${accessToken}` },
        json: {
          name: name.trim(),
          description: description.trim(),
          category,
          price: Number(price),
          compareAtPrice: compareAtPrice ? Number(compareAtPrice) : null,
          stock: Number(stock) || 0,
          status,
          tags: tagList,
          imageUrls: urls
        }
      });
      nav("/vendor/products");
    } catch (ex) {
      setErr(ex.message || "Save failed");
    } finally {
      setSaving(false);
    }
  };

  if (loading) return h("p", { className: "text-slate-500" }, "Loading product…");

  return h(f, null, [
    err && h("p", { className: "mb-4 text-sm text-rose-400" }, err),
    h("div", { className: "mb-6 flex flex-wrap items-center justify-between gap-3" }, [
      h("h1", { className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Edit product"),
      h(Link, { to: "/vendor/products" }, h(Button, { variant: "ghost", className: "!rounded-full" }, "← Back"))
    ]),
    h(GlassPanel, {}, [
      h("div", { className: "space-y-4" }, [
        h(Field, { label: "Product name" }, h(TextInput, { value: name, onChange: (e) => setName(e.target.value) })),
        h(Field, { label: "Description" }, h(TextArea, { value: description, onChange: (e) => setDescription(e.target.value) })),
        h("div", { className: "grid grid-cols-1 gap-4 sm:grid-cols-2" }, [
          h(Field, { label: "Price ($)" }, h(TextInput, { type: "number", step: "0.01", value: price, onChange: (e) => setPrice(e.target.value) })),
          h(Field, { label: "Compare at ($)" }, h(TextInput, { type: "number", step: "0.01", value: compareAtPrice, onChange: (e) => setCompareAtPrice(e.target.value) }))
        ]),
        h("div", { className: "grid grid-cols-1 gap-4 sm:grid-cols-2" }, [
          h(
            Field,
            { label: "Category" },
            h(
              SelectInput,
              { value: category, onChange: (e) => setCategory(e.target.value) },
              PRODUCT_CATEGORY_VALUES.map((c) => h("option", { key: c, value: c }, c))
            )
          ),
          h(Field, { label: "Stock" }, h(TextInput, { type: "number", value: stock, onChange: (e) => setStock(e.target.value) }))
        ]),
        h(Field, { label: "Status" }, h(SelectInput, { value: status, onChange: (e) => setStatus(e.target.value) }, [
          h("option", { value: "draft" }, "Draft"),
          h("option", { value: "active" }, "Active")
        ])),
        h(Field, { label: "Tags" }, h(TextInput, { value: tags, onChange: (e) => setTags(e.target.value) })),
        h(Field, { label: "Image URLs" }, h(TextArea, { value: imageUrls, onChange: (e) => setImageUrls(e.target.value) })),
        h(Button, { type: "button", onClick: save, loading: saving }, "Save changes")
      ])
    ])
  ]);
}

